# Code generated by MCHP Chatbot
import mimetypes
import os
import shutil
from datetime import datetime, timezone
from pathlib import Path
from typing import Optional, AsyncIterator
from urllib.parse import urlparse

from motor.motor_asyncio import AsyncIOMotorGridFSBucket

# Cloudinary support (optional)
try:
    import cloudinary
    import cloudinary.uploader
    import cloudinary.api
    CLOUDINARY_AVAILABLE = True
except ImportError:
    CLOUDINARY_AVAILABLE = False

UPLOAD_DIR = Path(__file__).parent / "uploads"
BUCKET_NAME = "media"
GRIDFS_CHUNK = 256 * 1024


def _cloudinary_configured() -> bool:
    """Check if Cloudinary is configured via CLOUDINARY_URL env var."""
    return CLOUDINARY_AVAILABLE and bool(os.getenv("CLOUDINARY_URL"))


def _init_cloudinary() -> None:
    """Initialize Cloudinary from CLOUDINARY_URL."""
    if _cloudinary_configured():
        cloudinary.config(cloudinary_url=os.getenv("CLOUDINARY_URL"))


def use_db_storage() -> bool:
    """Always use DB storage on Vercel, even if USE_DB_STORAGE is unset or wrong."""
    if os.getenv("VERCEL"):
        # **FORCE DB storage on Vercel for reliability:**
        return True
    flag = os.getenv("USE_DB_STORAGE", "").strip().lower()
    if flag in {"0", "false", "no"}:
        return False
    if flag in {"1", "true", "yes"}:
        return True
    return False


def _storage_backend() -> str:
    """Return the active storage backend: 'cloudinary', 'gridfs', or 'local'."""
    if _cloudinary_configured():
        return "cloudinary"
    if use_db_storage():
        return "gridfs"
    return "local"


def media_url(filename: str) -> str:
    """Public URL for a stored upload."""
    backend = _storage_backend()
    if backend == "cloudinary":
        # Cloudinary URLs are handled by the frontend directly
        # Return a special prefix that frontend can recognize
        return f"/api/media/cloudinary/{filename}"
    if backend == "gridfs":
        return f"/api/media/{filename}"
    return f"/uploads/{filename}"


def _bucket(db):
    return AsyncIOMotorGridFSBucket(db, bucket_name=BUCKET_NAME)


async def _delete_gridfs(db, filename: str) -> None:
    bucket = _bucket(db)
    cursor = bucket.find({"filename": filename})
    async for doc in cursor:
        await bucket.delete(doc._id)


def _content_type(filename: str) -> str:
    return mimetypes.guess_type(filename)[0] or "application/octet-stream"


async def _delete_cloudinary(filename: str) -> None:
    """Delete file from Cloudinary by public_id (filename without extension)."""
    if not _cloudinary_configured():
        return
    _init_cloudinary()
    public_id = Path(filename).stem
    try:
        cloudinary.uploader.destroy(public_id, resource_type="auto")
    except Exception:
        pass  # Ignore delete errors


async def save_upload(db, filename: str, data: bytes) -> None:
    print(f"[UPLOAD DEBUG] backend={_storage_backend()}, MONGO_URL={os.getenv('MONGO_URL')[:30] if os.getenv('MONGO_URL') else 'not set'}...")
    
    backend = _storage_backend()
    if backend == "cloudinary":
        _init_cloudinary()
        public_id = Path(filename).stem
        result = cloudinary.uploader.upload(
            data,
            public_id=public_id,
            resource_type="auto",
            overwrite=True,
        )
        # Store metadata in MongoDB for reference
        await db.media_metadata.update_one(
            {"filename": filename},
            {"$set": {
                "filename": filename,
                "cloudinary_public_id": public_id,
                "cloudinary_url": result.get("secure_url"),
                "cloudinary_format": result.get("format"),
                "bytes": len(data),
                "content_type": _content_type(filename),
                "updated_at": datetime.now(timezone.utc),
            }},
            upsert=True,
        )
        return

    if backend == "gridfs":
        await _delete_gridfs(db, filename)
        await _bucket(db).upload_from_stream(
            filename, data, metadata={"content_type": _content_type(filename)}
        )
        return

    UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
    (UPLOAD_DIR / filename).write_bytes(data)


async def save_upload_path(db, filename: str, path: Path) -> None:
    print(f"[UPLOAD DEBUG] backend={_storage_backend()}, MONGO_URL={os.getenv('MONGO_URL')[:30] if os.getenv('MONGO_URL') else 'not set'}...")
    
    backend = _storage_backend()
    if backend == "cloudinary":
        _init_cloudinary()
        public_id = Path(filename).stem
        result = cloudinary.uploader.upload(
            str(path),
            public_id=public_id,
            resource_type="auto",
            overwrite=True,
        )
        await db.media_metadata.update_one(
            {"filename": filename},
            {"$set": {
                "filename": filename,
                "cloudinary_public_id": public_id,
                "cloudinary_url": result.get("secure_url"),
                "cloudinary_format": result.get("format"),
                "bytes": path.stat().st_size,
                "content_type": _content_type(filename),
                "updated_at": datetime.now(timezone.utc),
            }},
            upsert=True,
        )
        return

    if backend == "gridfs":
        await _delete_gridfs(db, filename)
        with open(path, "rb") as handle:
            await _bucket(db).upload_from_stream(
                filename, handle, metadata={"content_type": _content_type(filename)}
            )
        return

    UPLOAD_DIR.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(path, UPLOAD_DIR / filename)


async def upload_size(db, filename: str) -> Optional[int]:
    """Ukuran berkas yang tersimpan (dipakai untuk mendukung Range/seek pemutar media)."""
    backend = _storage_backend()
    if backend == "cloudinary":
        doc = await db.media_metadata.find_one({"filename": filename}, {"_id": 0})
        return doc.get("bytes") if doc else None
    if backend == "gridfs":
        bucket = _bucket(db)
        try:
            grid_out = await bucket.open_download_stream_by_name(filename)
        except Exception:
            grid_out = None
        if grid_out is not None:
            return grid_out.length
        doc = await db.media.find_one({"filename": filename}, {"data": 0})
        if doc and doc.get("size"):
            return int(doc["size"])
        return None
    path = UPLOAD_DIR / filename
    return path.stat().st_size if path.is_file() else None


async def _cloudinary_range_iter(url: str, start: int, length: int) -> AsyncIterator[bytes]:
    """Fetch a byte range from Cloudinary URL."""
    import aiohttp
    headers = {"Range": f"bytes={start}-{start + length - 1}"}
    async with aiohttp.ClientSession() as session:
        async with session.get(url, headers=headers) as resp:
            async for chunk in resp.content.iter_chunked(GRIDFS_CHUNK):
                yield chunk


async def open_upload_range(db, filename: str, start: int, length: int) -> Optional[AsyncIterator[bytes]]:
    """Kembalikan iterator async untuk potongan berkas [start, start+length)."""
    backend = _storage_backend()
    if backend == "cloudinary":
        doc = await db.media_metadata.find_one({"filename": filename}, {"_id": 0})
        if not doc or not doc.get("cloudinary_url"):
            return None
        return _cloudinary_range_iter(doc["cloudinary_url"], start, length)

    if backend == "gridfs":
        bucket = _bucket(db)
        try:
            grid_out = await bucket.open_download_stream_by_name(filename)
        except Exception:
            grid_out = None
        if grid_out is not None:
            grid_out.seek(start)
            remaining = length

            async def grid_range_iter():
                nonlocal remaining
                while remaining > 0:
                    chunk = await grid_out.read(min(GRIDFS_CHUNK, remaining))
                    if not chunk:
                        break
                    remaining -= len(chunk)
                    yield chunk

            return grid_range_iter()
        doc = await db.media.find_one({"filename": filename})
        if not doc or not doc.get("data"):
            return None
        data = doc["data"][start:start + length]

        async def legacy_range_iter():
            yield data

        return legacy_range_iter()

    path = UPLOAD_DIR / filename
    if not path.is_file():
        return None

    async def disk_range_iter():
        with open(path, "rb") as handle:
            handle.seek(start)
            remaining = length
            while remaining > 0:
                chunk = handle.read(min(GRIDFS_CHUNK, remaining))
                if not chunk:
                    break
                remaining -= len(chunk)
                yield chunk

    return disk_range_iter()


async def open_upload(db, filename: str):
    """Kembalikan (iterator async byte, content_type) atau (None, None)."""
    backend = _storage_backend()
    if backend == "cloudinary":
        doc = await db.media_metadata.find_one({"filename": filename}, {"_id": 0})
        if not doc or not doc.get("cloudinary_url"):
            return None, None
        content_type = doc.get("content_type") or _content_type(filename)

        async def cloudinary_iter():
            import aiohttp
            async with aiohttp.ClientSession() as session:
                async with session.get(doc["cloudinary_url"]) as resp:
                    async for chunk in resp.content.iter_chunked(GRIDFS_CHUNK):
                        yield chunk

        return cloudinary_iter(), content_type

    if backend == "gridfs":
        bucket = _bucket(db)
        grid_out = None
        try:
            grid_out = await bucket.open_download_stream_by_name(filename)
        except Exception:
            grid_out = None

        if grid_out is not None:
            metadata = getattr(grid_out, "metadata", None) or {}
            content_type = metadata.get("content_type") or _content_type(filename)

            async def grid_iter():
                while True:
                    chunk = await grid_out.read(GRIDFS_CHUNK)
                    if not chunk:
                        break
                    yield chunk

            return grid_iter(), content_type

        doc = await db.media.find_one({"filename": filename})
        if not doc or not doc.get("data"):
            return None, None
        data = doc["data"]
        content_type = doc.get("content_type") or "application/octet-stream"

        async def legacy_iter():
            yield data

        return legacy_iter(), content_type

    path = UPLOAD_DIR / filename
    if not path.is_file():
        return None, None
    content_type = _content_type(path.name)

    async def disk_iter():
        with open(path, "rb") as handle:
            while True:
                chunk = handle.read(GRIDFS_CHUNK)
                if not chunk:
                    break
                yield chunk

    return disk_iter(), content_type